import java.nio.*;import java.nio.file.*;import java.util.*;import com.google.gson.*;import org.lwjgl.glfw.GLFW;import org.lwjgl.opengl.*;import com.iridium126.createmanaindustry.client.particles.engine.hardware.*;
/** Paged exact geometry at Q=0, workgroup edges, overlap and far-coordinate fallback. */
public final class R8EdgeGpu extends ModelPopulationGpuValidation{
 public static void main(String[]args)throws Exception{Path out=Path.of(System.getProperty("cmi.benchmark.output"));Files.createDirectories(out);R8SequenceGpu.source=out.resolve("source");Files.createDirectory(R8SequenceGpu.source);for(String f:List.of("Query.h","grid.cu","rt.cu","rt-triangle.cu","tensor.cu"))Files.copy(Path.of("native/offload",f),R8SequenceGpu.source.resolve(f));R8SequenceGpu.deps=JsonParser.parseString(Files.readString(Path.of(".gradle/neighbor-rt/dependencies.json"))).getAsJsonObject();check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,6);long w=GLFW.glfwCreateWindow(32,32,"R8 edge geometry",0,0);GLFW.glfwMakeContextCurrent(w);GL.createCapabilities();HardwareNative.load(Path.of(".gradle/hardware-offload/build"));var cases=new ArrayList<Object>();for(int backend=0;backend<3;backend++)try(var runner=new R8SequenceGpu.Runner(new R8SequenceGpu.Mode("edge",backend,7,1))){for(int n:new int[]{0,1,63,64,65,257,1000})for(float origin:new float[]{0,-32,1_000_000,-30_000_000})for(boolean noQueries:new boolean[]{false,true}){int q=noQueries?0:n,ro=R8SequenceGpu.align(64+n*16),oo=R8SequenceGpu.align(ro+q*16),map=R8SequenceGpu.align(oo+q*4);var packet=bytes(map+n*4).putInt(0,0x52374931).putInt(4,1).putInt(16,n).putInt(20,q).putInt(24,1).putFloat(28,1).putInt(32,64).putInt(36,ro).putInt(40,oo).putInt(44,map).putInt(48,n).putLong(56,71);var pts=bytes(n*16);var req=bytes(q*16);var own=bytes(q*4);for(int i=0;i<n;i++){float x=origin+(i%3)*.25f;pts.putFloat(i*16,x).putFloat(i*16+4,origin).putFloat(i*16+8,origin);packet.putFloat(64+i*16,x).putFloat(68+i*16,origin).putFloat(72+i*16,origin).putInt(map+i*4,i);if(i<q){req.putFloat(i*16,x).putFloat(i*16+4,origin).putFloat(i*16+8,origin).putFloat(i*16+12,1);own.putInt(i*4,i);packet.putFloat(ro+i*16,x).putFloat(ro+i*16+4,origin).putFloat(ro+i*16+8,origin).putFloat(ro+i*16+12,1).putInt(oo+i*4,i);}}R8SequenceGpu.packets=new ByteBuffer[]{packet};R8SequenceGpu.points=new ByteBuffer[]{pts};R8SequenceGpu.requests=new ByteBuffer[]{req};R8SequenceGpu.owners=new ByteBuffer[]{own};R8SequenceGpu.ns=new int[]{n};R8SequenceGpu.qs=new int[]{q};R8SequenceGpu.sceneFrames=new int[]{0};R8SequenceGpu.cellSize=1;runner.run(0,R8SequenceGpu.reference(0));cases.add(Map.of("backend",backend,"n",n,"q",q,"origin",origin));}}check(GL11.glGetError()==0,"edge GL state");Files.writeString(out.resolve("edges.json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("passed",true,"checks",checks,"cases",cases)));GLFW.glfwDestroyWindow(w);GLFW.glfwTerminate();}
}
